#!/bin/sh
set -eu

ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
cd "$ROOT"

if [ "$(id -u)" -ne 0 ]; then
    echo "Run with sudo: sudo ./scripts/build-iso.sh" >&2
    exit 1
fi

command -v lb >/dev/null 2>&1 || {
    echo "live-build is missing. Run ./scripts/install-dependencies.sh first." >&2
    exit 1
}

configure_build() {
    # These files are generated by live-build and may contain stale values.
    rm -f config/binary config/bootstrap config/chroot config/common config/source
    rm -f config/package-lists/live.list.chroot
    lb config
}

mkdir -p build
# Rebuild generated stages so package/config changes are applied; --all keeps
# downloaded package and bootstrap caches.
lb clean --all
configure_build

if ! lb build; then
    echo "Primary Debian mirror build failed; retrying with official Debian mirrors." >&2
    export DEVOS_DEBIAN_MIRROR="http://deb.debian.org/debian/"
    export DEVOS_SECURITY_MIRROR="http://security.debian.org/"
    lb clean --all
    configure_build
    lb build
fi

set -- ./*.iso
if [ ! -f "$1" ]; then
    echo "Build completed but no ISO was found." >&2
    exit 1
fi
mv -- "$1" build/devos-amd64.iso
echo "Created: $ROOT/build/devos-amd64.iso"
